class PriorityQueue {
    constructor() {
        this.elements = [];
    }
    enqueue(element, priority) {
        let added = false;
        for (let i = 0; i < this.elements.length; i++) {
            if (priority < this.elements[i].priority) {
                this.elements.splice(i, 0, { element, priority });
                added = true;
                break;
            }
        }
        if (!added) {
            this.elements.push({ element, priority });
        }
