    d %= n;
    // Calculate the number of cycles in the rotation
    int cycles = __gcd(n, d);
    // Process each cycle
    for (int i = 0; i < cycles; i++) {
        // Start index of current cycle
        int currIdx = i;
        int currEle = arr[currIdx];
        // Rotate elements till we reach the start of cycle
