function serialize(root) {
    const arr = [];
    const q = new Queue();
    q.enqueue(root);
    while (!q.isEmpty()) {
        const curr = q.dequeue();
        // If curr node is null,
        // append -1 to result.
        if (curr === null) {
            arr.push(-1);
            continue;
        }
        // else push its value into result
        arr.push(curr.data);
        // enqueue children
        q.enqueue(curr.left);
        q.enqueue(curr.right);
    }
    return arr;
